/// `textUnderlineOffset` and `textDecorationThickness` as motion, CSS transition and keyframe targets, against
/// the computed values headless Chrome reports (`fixtures/text-decoration-motion-oracle.json`, regenerated by
/// `fixtures/text-decoration-motion-oracle.sh`). What is read back is the underline that is painted: the rows
/// it fills at a time of the animation are those of the same text styled with Chrome's computed value, which
/// `text-decoration-oracle.test.tsx` holds to Chrome's pixels.

import fs from "fs"
import path from "path"
import React, { type CSSProperties } from "react"
import { fileURLToPath } from "url"
import { describe, expect, it } from "vitest"
import { motion } from "../index"
import { createTestRoot, hasNativeTestRenderer } from "../testing.js"
import { readPixels, SHOTS_DIR } from "./test-utils.js"

const describeNative = hasNativeTestRenderer ? describe : describe.skip

type Style = Record<string, unknown>

interface Case {
  kind: "waapi" | "transition"
  prop: "textUnderlineOffset" | "textDecorationThickness"
  keyframes?: Style[] | Style
  base?: string
  after?: Style
  style: string
  /** What the element's parent declares, which the element inherits. */
  parent?: string
  animations: number
  samples: Record<string, string>
  error?: string
}

const ORACLE: Record<string, Case> = JSON.parse(
  fs.readFileSync(
    path.resolve(path.dirname(fileURLToPath(import.meta.url)), "fixtures/text-decoration-motion-oracle.json"),
    "utf8"
  )
).cases

const TIMES = [0, 0.25, 0.5, 0.75, 1]
const linear = { duration: 1, ease: "linear" } as const
const UNDERLINE = { textDecoration: "underline #ff0000", fontSize: 16, lineHeight: "24px" } as const

let shots = 0

/** The rows of red pixels the current frame has. */
function underlineRows(renderer: ReturnType<typeof createTestRoot>["renderer"]): number[] {
  const file = `${SHOTS_DIR}/text-decoration-motion-${shots++}.png`
  renderer.captureScreenshot(file)
  const pixels = readPixels(file)
  const rows: number[] = []
  for (let y = 0; y < 80; y++) {
    let red = 0
    for (let x = 0; x < 200; x++) {
      const [r, g, b] = pixels.at(x, y)
      if (r > 200 && g < 60 && b < 60) red++
    }
    if (red >= 8) rows.push(y)
  }
  return rows
}

function frame(style: Style, animation: Record<string, unknown> | undefined, base: Style): React.ReactElement {
  const box = { ...UNDERLINE, ...base, ...style } as CSSProperties
  return animation ? (
    <motion.div style={box} initial={animation.initial as never} animate={animation.animate as never} transition={linear}>
      xxxx
    </motion.div>
  ) : (
    <div style={box}>xxxx</div>
  )
}

/** `element` inside the parent the case declares, which it inherits from. */
function under(data: Case, element: React.ReactElement): React.ReactElement {
  return data.parent ? <div style={styleOf(data.parent) as CSSProperties}>{element}</div> : element
}

/** The rows painted at each of `TIMES` while the case runs. */
function animatedRows(data: Case): number[][] {
  const { render, renderer, unmount } = createTestRoot({ width: 300, height: 100 })
  try {
    renderer.clockPause()
    const base = styleOf(data.style)
    if (data.kind === "waapi") {
      const initial: Style = {}
      const animate: Style = {}
      for (const [prop, value] of Object.entries(Array.isArray(data.keyframes) ? mergeFrames(data.keyframes) : data.keyframes!)) {
        if (Array.isArray(value)) {
          initial[prop] = value[0]
          animate[prop] = value[1]
        } else {
          animate[prop] = value
        }
      }
      render(under(data, frame({}, { initial: Object.keys(initial).length ? initial : { opacity: 1 }, animate }, base)))
    } else {
      const css = styleOf(data.base!)
      const transition = { transition: data.after && "" }
      void transition
      render(under(data, frame({ ...css, transition: transitionOf(data) }, undefined, base)))
      renderer.flush()
      render(under(data, frame({ ...css, ...data.after, transition: transitionOf(data) }, undefined, base)))
    }
    renderer.flush()
    let elapsed = 0
    return TIMES.map((time) => {
      renderer.clockFastForward(time * 1000 - elapsed)
      elapsed = time * 1000
      renderer.flush()
      return underlineRows(renderer)
    })
  } finally {
    unmount()
  }
}

/** The one value of each property of a pair of keyframes, `[from, to]`. */
function mergeFrames(frames: Style[]): Style {
  const merged: Style = {}
  for (const key of Object.keys(frames[0]!)) merged[key] = [frames[0]![key], frames[1]![key]]
  return merged
}

function styleOf(css: string): Style {
  const style: Style = {}
  for (const declaration of css.split(";").filter(Boolean)) {
    const [name, value] = declaration.split(":")
    style[name!.trim().replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase())] = value!.trim()
  }
  return style
}

function transitionOf(data: Case): string {
  const name = data.prop === "textUnderlineOffset" ? "text-underline-offset" : "text-decoration-thickness"
  return `${name} 1s linear${data.animations && /allow-discrete/.test(JSON.stringify(data)) ? " allow-discrete" : ""}`
}

/** The rows painted for the style that has `value` from the start. */
function staticRows(data: Case, value: string): number[] {
  const { render, renderer, unmount } = createTestRoot({ width: 300, height: 100 })
  try {
    render(under(data, frame({ [data.prop]: value }, undefined, styleOf(data.style))))
    renderer.flush()
    return underlineRows(renderer)
  } finally {
    unmount()
  }
}

describeNative("text decoration lengths in motion, against Chrome's computed values", () => {
  for (const [name, data] of Object.entries(ORACLE)) {
    if (data.error) continue
    it(name, () => {
      const painted = animatedRows(data)
      TIMES.forEach((time, index) => {
        const value = data.samples[String(time)]!
        expect(painted[index], `${name} at ${time} should be painted as ${value}`).toEqual(staticRows(data, value))
      })
    })
  }
})

describeNative("the underline of a span in motion", () => {
  const paragraph = (style: Style) => (
    <div style={{ fontSize: 16, lineHeight: "24px", color: "#000000" }}>
      <text>
        <span style={{ textDecoration: "underline #ff0000", ...style }}>xxxxxx</span>
      </text>
    </div>
  )

  function rowsAt(style: Style, steps: number[] = []): number[][] {
    const { render, renderer, unmount } = createTestRoot({ width: 300, height: 100 })
    try {
      renderer.clockPause()
      render(paragraph(style))
      renderer.flush()
      return [underlineRows(renderer), ...steps.map((ms) => {
        renderer.clockFastForward(ms)
        renderer.flush()
        return underlineRows(renderer)
      })]
    } finally {
      unmount()
    }
  }

  it("transitions the offset and the thickness through the paragraph", () => {
    const transition = "text-underline-offset 1s linear, text-decoration-thickness 1s linear"
    const { render, renderer, unmount } = createTestRoot({ width: 300, height: 100 })
    let animated: number[][]
    try {
      renderer.clockPause()
      render(paragraph({ textUnderlineOffset: "2px", textDecorationThickness: "2px", transition }))
      renderer.flush()
      render(paragraph({ textUnderlineOffset: "10px", textDecorationThickness: "6px", transition }))
      renderer.flush()
      animated = [0, 500, 500].map((ms) => {
        renderer.clockFastForward(ms)
        renderer.flush()
        return underlineRows(renderer)
      })
    } finally {
      unmount()
    }
    expect(animated[0]).toEqual(rowsAt({ textUnderlineOffset: "2px", textDecorationThickness: "2px" })[0])
    expect(animated[1]).toEqual(rowsAt({ textUnderlineOffset: "6px", textDecorationThickness: "4px" })[0])
    expect(animated[2]).toEqual(rowsAt({ textUnderlineOffset: "10px", textDecorationThickness: "6px" })[0])
  })
})
